sys_properties.value:
[
{
    "kpi": "Installations Without Software Models",
    "description": "Software installations missing associated software models can cause challenges in license tracking and compliance management.",
    "table": "cmdb_sam_sw_install",
    "query": "active=true^assigned_toISNOTEMPTY^discovery_model.modelISEMPTY"
},
{
    "kpi": "Installations Without Associated Discovery Models",
    "description": "software installations in the system that are not linked to a discovery model, potentially causing inconsistencies in asset management and licensing compliance.",
    "table": "cmdb_sam_sw_install",
    "query": "assigned_toISNOTEMPTY^active=true^discovery_modelISEMPTY"
},
{
    "kpi": "Installations Missing Ownership Information",
    "description": "Software installations without ownership information may result in accountability issues and delayed resolution of software-related incidents.",
    "table": "cmdb_sam_sw_install",
    "query": "active=true^assigned_toISEMPTY"
},
{
    "kpi": "Number of Installation With unused user records",
    "description": "Tracks the last time the software was used. This helps identify unused or underutilized software for potential reclamation or license reallocation.",
    "table": "cmdb_sam_sw_install",
    "query": "assigned_toISNOTEMPTY^active=true^last_used<javascript:gs.beginningOfLast3Months()"
},
{
    "kpi": "Number of Installations Without Product Name",
    "description": "Installations where the product name is missing. This helps ensure that all software installations are properly tracked and associated with their corresponding product for accurate license management and reporting.",
    "table": "cmdb_sam_sw_install",
    "query": "active=true^norm_productISEMPTY"
},
{
    "kpi": "Number of Installations Without Publisher",
    "description": "Installations where the publisher information is missing. Without the publisher, it becomes challenging to manage software licenses, ensure compliance with licensing agreements.",
    "table": "cmdb_sam_sw_install",
    "query": "active=true^norm_publisherISEMPTY"
}
 ]
